"""Compare decoded public N8BW data with generated bytes and endpoint captures.

Search only for CRC-valid hello/GO and first sequence-one header. Control text at
an old baud can legitimately frame-error; restrict confidence to the bulk window.
No missing capture tail may be called destination loss.
"""
import argparse,json
from pathlib import Path
from modem_bw_protocol import frame,pattern,UP,DOWN,check

def compare(wire,endpoint,salt,frames):
 first=frame(1,pattern(1,salt));start=wire.find(first[:16])
 if start<0:return {'complete_start':False,'reason':'No exact first frame header'}
 bulk=wire[start:];wanted=bytearray()
 for seq in range(1,frames+1):wanted.extend(frame(seq,pattern(seq,salt)))
 wanted.extend(frame(frames+1))
 # Tail can include EOS, escape and AT; parse valid deterministic frames first.
 n=0;count=0
 while len(bulk)-n>=16:
  try:
   length=int.from_bytes(bulk[n+8:n+12],'little');size=16+length
   _,payload=check(bulk[n:n+size],seq=count+1,salt=salt)
  except ValueError:break
  n+=size
  if not payload:break
  count+=1
 mismatch=next((i for i,(a,b) in enumerate(zip(bulk,wanted)) if a!=b),None)
 dest=endpoint or b'';different=next((i for i,(a,b) in enumerate(zip(bulk,dest)) if a!=b),None)
 return dict(complete_start=True,wire_start_offset=start,expected_payload_frames=frames,expected_wire_bytes=len(wanted),capture_covers_expected_length=len(bulk)>=len(wanted),valid_payload_frames=count,valid_prefix_bytes=n,first_wire_vs_expected_difference=mismatch,first_wire_vs_endpoint_difference=different,endpoint_bytes=len(dest),endpoint_is_wire_prefix=bulk.startswith(dest),endpoint_complete_comparison=bool(dest) and len(dest)<=len(bulk))
def main():
 p=argparse.ArgumentParser();p.add_argument('arm',type=Path);p.add_argument('decoded',type=Path);p.add_argument('--direction',choices=['up','down'],required=True);a=p.parse_args()
 name='p4-tx' if a.direction=='up' else 'esp-tx';endpoint=(a.arm/'pi/received.bin').read_bytes() if a.direction=='up' else None
 arm=json.loads((a.arm/'result.json').read_text());frames=arm['native']['tx_frames'] if a.direction=='up' else arm['pi']['tx_frames']
 result=compare((a.decoded/(name+'.bin')).read_bytes(),endpoint,UP if a.direction=='up' else DOWN,frames)
 result['scope']='Bulk prefix comparison; independently check sample coverage, framing errors, EOS and endpoint terminal counts before localization'
 (a.decoded/'comparison.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result))
if __name__=='__main__':main()
